it.effect("keeps concurrent host environments isolated from the ambient process", () =>
  Effect.gen(function* () {
    const [first, second] = yield* Effect.all([
      mergeProviderInstanceEnvironment(undefined).pipe(
        Effect.provideService(HostProcess.Environment, { PATH: "/first/bin" }),
      ),
      mergeProviderInstanceEnvironment([
        { name: "PROVIDER_MODEL", value: "selected", sensitive: false },
      ]).pipe(
        Effect.provideService(HostProcess.Environment, { PATH: "/second/bin" }),
      ),
    ], { concurrency: "unbounded" });
    // Compare only approved fields; a failure must not print ambient secrets.
    expect(first.PATH === "/first/bin").toBe(true);
    expect(Object.keys(first)).toEqual(["PATH"]);
    expect(second.PATH === "/second/bin").toBe(true);
    expect(second.PROVIDER_MODEL).toBe("selected");
    expect(Object.keys(second).sort()).toEqual(["PATH", "PROVIDER_MODEL"]);
  }),
);
